"use client";

import * as React from "react";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { fieldOpen, formFieldBase, formFieldSingleLine } from "./_shared";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "./command";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";

const statuses = [
  { value: "backlog", label: "Backlog" },
  { value: "todo", label: "To do" },
  { value: "in-progress", label: "In progress" },
  { value: "in-review", label: "In review" },
  { value: "done", label: "Done" },
];

/**
 * Margin combobox: the grey filled field that opens a searchable list on the
 * white floating panel, as wide as the field, with an oxblood tick on the chosen row.
 */
export function ComboboxDemo() {
  const [open, setOpen] = React.useState(false);
  const [value, setValue] = React.useState("");
  const selected = statuses.find((status) => status.value === value);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger
        role="combobox"
        aria-expanded={open}
        data-slot="combobox-trigger"
        className={cn(
          formFieldBase,
          formFieldSingleLine,
          "w-56 cursor-default items-center justify-between gap-2 text-start",
          fieldOpen,
          !selected && "text-muted-foreground",
        )}
      >
        <span className="truncate">{selected ? selected.label : "Set status"}</span>
        <Icon icon="solar:sort-vertical-linear" className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
      </PopoverTrigger>
      <PopoverContent align="start" className="w-(--anchor-width) gap-0 p-0">
        <Command className="bg-transparent shadow-none">
          <CommandInput placeholder="Search statuses" />
          <CommandList>
            <CommandEmpty>No status found.</CommandEmpty>
            <CommandGroup>
              {statuses.map((status) => (
                <CommandItem
                  key={status.value}
                  value={status.value}
                  onSelect={(currentValue: string) => {
                    setValue(currentValue === value ? "" : currentValue);
                    setOpen(false);
                  }}
                >
                  {status.label}
                  <Icon
                    icon="solar:unread-linear"
                    className={cn(
                      "ms-auto text-(--primary-text)!",
                      value === status.value ? "opacity-100" : "opacity-0",
                    )}
                    aria-hidden="true"
                  />
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}
